using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class StrategyDraftFileStore{private readonly string _root;private static readonly JsonSerializerOptions Options=new(){WriteIndented=true};public StrategyDraftFileStore(string root){if(string.IsNullOrWhiteSpace(root))throw new ArgumentException("A draft store root is required.",nameof(root));_root=Path.GetFullPath(root);}public string Save(StrategyDraft value){StrategyDraftRules.Validate(value);var dir=Path.Combine(_root,value.DraftFingerprint);var path=Path.Combine(dir,"strategy-draft.json");Directory.CreateDirectory(dir);var json=JsonSerializer.Serialize(value,Options);if(File.Exists(path)&&!string.Equals(File.ReadAllText(path,Encoding.UTF8),json,StringComparison.Ordinal))throw new InvalidOperationException("Strategy draft fingerprint collision contains different content.");File.WriteAllText(path,json,new UTF8Encoding(false));return path;}public StrategyDraft Load(string fingerprint){var path=Path.Combine(_root,Safe(fingerprint),"strategy-draft.json");var value=JsonSerializer.Deserialize<StrategyDraft>(File.ReadAllText(path,Encoding.UTF8),Options)??throw new InvalidOperationException("Strategy draft JSON is invalid.");if(value.DraftFingerprint!=fingerprint)throw new InvalidOperationException("Stored strategy draft identity does not match its key.");StrategyDraftRules.Validate(value);return value;}private static string Safe(string value){if(string.IsNullOrWhiteSpace(value)||value.Any(ch=>!(char.IsLetterOrDigit(ch)||ch is '-' or '_')))throw new ArgumentException("Unsafe draft fingerprint.",nameof(value));return value;}}
